function required_excel_upload(string $key,string $label='archivo Excel'): array {
    if(!isset($_FILES[$key])||!is_array($_FILES[$key]))throw new RuntimeException('Selecciona el '.$label.' obligatorio.');
    $file=$_FILES[$key];$error=(int)($file['error']??UPLOAD_ERR_NO_FILE);
    if($error!==UPLOAD_ERR_OK){
        $messages=[UPLOAD_ERR_INI_SIZE=>'El archivo supera el límite permitido por el servidor.',UPLOAD_ERR_FORM_SIZE=>'El archivo supera el tamaño permitido.',UPLOAD_ERR_PARTIAL=>'El archivo se cargó de forma incompleta. Intenta nuevamente.',UPLOAD_ERR_NO_FILE=>'Selecciona el '.$label.' obligatorio.',UPLOAD_ERR_NO_TMP_DIR=>'El servidor no tiene disponible la carpeta temporal de carga.',UPLOAD_ERR_CANT_WRITE=>'El servidor no pudo escribir el archivo temporal.',UPLOAD_ERR_EXTENSION=>'Una extensión del servidor bloqueó la carga del archivo.'];
        throw new RuntimeException($messages[$error]??'No se pudo recibir el archivo. Código de carga: '.$error.'.');
    }
    $tmp=(string)($file['tmp_name']??'');if($tmp===''||!is_uploaded_file($tmp))throw new RuntimeException('No se recibió correctamente el '.$label.'. Vuelve a seleccionarlo.');
    $size=(int)($file['size']??0);if($size<=0)throw new RuntimeException('El archivo seleccionado está vacío.');if($size>10*1024*1024)throw new RuntimeException('El archivo no puede superar 10 MB.');
    $ext=strtolower(pathinfo((string)($file['name']??''),PATHINFO_EXTENSION));if(!in_array($ext,['xlsx','csv'],true))throw new RuntimeException('Formato no permitido. Usa un archivo .xlsx o .csv.');
    return [$file,$ext];
}

function read_csv_rows(string $path): array {
    $fh=fopen($path,'rb');if($fh===false)throw new RuntimeException('No se pudo abrir el archivo CSV.');
    $sample=(string)fgets($fh);rewind($fh);$candidates=[',',';',"\t"];$delimiter=',';$best=-1;
    foreach($candidates as $candidate){$count=substr_count($sample,$candidate);if($count>$best){$best=$count;$delimiter=$candidate;}}
    $rows=[];while(($row=fgetcsv($fh,0,$delimiter))!==false){if(isset($row[0]))$row[0]=preg_replace('/^\xEF\xBB\xBF/', '', (string)$row[0])??(string)$row[0];$rows[]=$row;}fclose($fh);return $rows;
}

