$flash=pull_flash();$app=setting('app_name','Evaluación Corporativa');$browserTitle=browser_title();$favicon=site_favicon('../');$adminLogo=setting('logo_path','');
function navActive(string $p,string $page):string{return $p===$page?'active':'';}
function pageTitle(string $page):string{return ['dashboard'=>'Dashboard','employees'=>'Empleados','questions'=>'Preguntas','games'=>'Juegos','reports'=>'Reportes','settings'=>'Configuración','email'=>'Correo','users'=>'Usuarios'][$page]??'Administración';}
function renderKpi(string $icon,string $label,string $value,string $hint=''):void{?><article class="kpi motion-card"><span class="kpi-icon"><?=ui_icon($icon)?></span><div><small><?=e($label)?></small><strong data-counter><?=e($value)?></strong><?php if($hint!==''):?><em><?=e($hint)?></em><?php endif;?></div></article><?php }
function renderListToolbar(string $id,int $total,string $placeholder='Buscar registros...',int $size=12):void{?><div class="list-toolbar" data-list-toolbar><div class="list-total"><strong data-list-visible><?=$total?></strong><span>de <?=$total?> registros</span></div><div class="list-tools"><label class="list-search"><?=ui_icon('search')?><input type="search" placeholder="<?=e($placeholder)?>" data-list-search autocomplete="off" value="<?=e((string)($_GET['q']??''))?>"><button type="button" class="search-clear" data-list-clear aria-label="Limpiar búsqueda"><?=ui_icon('x')?></button></label><label class="records-size"><span>Mostrar</span><select data-list-size><option value="6" <?=$size===6?'selected':''?>>6</option><option value="12" <?=$size===12?'selected':''?>>12</option><option value="24">24</option><option value="48">48</option><option value="all">Todos (<?=$total?>)</option></select></label><div class="view-switch" role="group" aria-label="Cambiar vista"><button type="button" data-list-view="detail" title="Vista detalle" aria-label="Vista detalle"><?=ui_icon('list')?><span>Detalle</span></button><button type="button" class="active" data-list-view="mini" title="Vista miniatura" aria-label="Vista miniatura"><?=ui_icon('cards')?><span>Miniatura</span></button></div></div></div><?php }
