ired">*</span></p><?php for($i=0;$i<4;$i++):?><label class="option-edit-row"><input type="checkbox" name="correct_indices[]" value="<?=$i?>" data-correct-option><span class="premium-check-box"></span><input name="options[]" placeholder="Opción <?=$i+1?>" <?=$i<2?'required':''?>></label><?php endfor;?></div><div class="helper-note" data-question-correct-help><?=ui_icon('check')?> Marca una opción correcta. En selección múltiple marca exactamente la cantidad configurada.</div><div class="modal-actions"><button type="button" class="btn ghost" data-modal-close><?=ui_icon('x')?> Cancelar</button><button class="btn primary" type="submit"><?=ui_icon('save')?> Guardar pregunta</button></div></form></div></div>
