$rows=(new ReportService())->rows();$passing=(float)setting('passing_score','70');$passed=count(array_filter($rows,fn($r)=>(float)$r['score']>=$passing));$avg=count($rows)?array_sum(array_map(fn($r)=>(float)$r['score'],$rows))/count($rows):0;$totalEmp=(int)$pdo->query("SELECT COUNT(*) FROM employees WHERE status='active'")->fetchColumn();$participation=$totalEmp?round(count($rows)/$totalEmp*100,1):0;
$gameRows=(new GameAttemptReportService())->rows();$gamePlayers=count(array_unique(array_filter(array_map(fn($r)=>(string)$r['badge'],$gameRows))));$gameAvg=count($gameRows)?array_sum(array_map(fn($r)=>(float)$r['score'],$gameRows))/count($gameRows):0;$gamesPlayed=count(array_unique(array_map(fn($r)=>(string)$r['game'],$gameRows)));$gameParticipation=$totalEmp?round($gamePlayers/$totalEmp*100,1):0;
$people=$pdo->query("SELECT emp.id,emp.badge,emp.name,emp.department,
 COALESCE(ev.correct_answers,0) eval_correct,COALESCE(ev.total_questions,0) eval_total,COALESCE(ev.score,0) eval_score,COALESCE(ev.accuracy_score,ev.score,0) eval_accuracy,COALESCE(ev.response_seconds,0) eval_time,
 COUNT(DISTINCT CASE WHEN ga.completed_at IS NOT NULL THEN ga.game_id END) games_completed,COALESCE(AVG(CASE WHEN ga.completed_at IS NOT NULL THEN ga.score END),0) game_avg,
 COALESCE(SUM(CASE WHEN ga.completed_at IS NOT NULL THEN ga.correct_answers ELSE 0 END),0) game_correct,COALESCE(SUM(CASE WHEN ga.completed_at IS NOT NULL THEN ga.total_items ELSE 0 END),0) game_total,
 COALESCE(SUM(CASE WHEN ga.completed_at IS NOT NULL THEN ga.response_seconds ELSE 0 END),0) game_time
 FROM employees emp LEFT JOIN evaluations ev ON ev.employee_id=emp.id AND ev.status='completed' LEFT JOIN game_attempts ga ON ga.employee_id=emp.id AND ga.completed_at IS NOT NULL
 WHERE ev.id IS NOT NULL OR ga.id IS NOT NULL GROUP BY emp.id,emp.badge,emp.name,emp.department,ev.correct_answers,ev.total_questions,ev.score,ev.accuracy_score,ev.response_seconds
 ORDER BY (COALESCE(ev.correct_answers,0)+COALESCE(SUM(CASE WHEN ga.completed_at IS NOT NULL THEN ga.correct_answers ELSE 0 END),0)) DESC,(COALESCE(ev.response_seconds,0)+COALESCE(SUM(CASE WHEN ga.completed_at IS NOT NULL THEN ga.response_seconds ELSE 0 END),0)) ASC,emp.name")->fetchAll();
